import json, sys
data = json.load(sys.stdin)
for p, methods in data.get('paths', {}).items():
    print(p)
    for m, spec in methods.items():
        if m != 'parameters':
            print(f'  {m.upper()}: {spec.get(\"operationId\", \"\")}')
